import time
import signal
import sys
import spidev

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 50000
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def read_raw_data(self):
        try:
            response = self.spi.xfer2([0b00000001, 0b10000000, 0b00000000])
            return ((response[1] & 0b00000011) << 8) | response[2]
        except OSError as e:
            print(f"Error reading from SPI device: {e}")
            sys.exit(1)

    def convert_to_weight(self, raw_data):
        return raw_data * 0.000244140625

    def close(self):
        self.spi.close()

def signal_handler(signal, frame):
    print("Received SIGTERM, shutting down")
    sys.exit(0)

def main():
    signal.signal(signal.SIGTERM, signal_handler)
    load_cell_reader = LoadCellReader()
    try:
        while True:
            raw_data = load_cell_reader.read_raw_data()
            weight = load_cell_reader.convert_to_weight(raw_data)
            print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Received KeyboardInterrupt, shutting down")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        load_cell_reader.close()
        print("Shutdown complete")

if __name__ == "__main__":
    main()

