# Parse command line arguments
parser = argparse.ArgumentParser(description='Smart irrigation system')
parser.add_argument('--moisture_threshold', type=int, default=30,
                    help='Moisture threshold (default: 30)')
parser.add_argument('--web_port', type=int, default=8080,
                    help='TCP port for web interface (default: 8080)')
parser.add_argument('--log_file', type=str, default='irrigation.log',
                    help='Log file (default: irrigation.log)')
parser.add_argument('--valve_pin', type=int, default=17,
                    help='GPIO pin for valve (default: 17)')
parser.add_argument('--spi_channel', type=int, default=0,
                    help='SPI channel (default: 0)')
args = parser.parse_args()

# Set up logging
logging.basicConfig(filename=args.log_file, level=logging.INFO)

# Set up GPIO
valve = gpiozero.OutputDevice(args.valve_pin)

# Set up SPI
spi = spidev.SpiDev()
spi.open(0, args.spi_channel)
spi.max_speed_hz = 1000000

# Set up TCP server
server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
