import time
import logging
import queue
import threading
import argparse
import spidev
import RPi.GPIO as GPIO

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.gpio = None
        self.stop_event = threading.Event()
        self.thread = None
        self.init_spi()
        self.init_gpio()

    def init_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
        except Exception as e:
            logging.error(f'Error initializing SPI: {e}')

    def init_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pins, GPIO.IN)
        except Exception as e:
            logging.error(f'Error initializing GPIO: {e}')

    def read_spi(self):
        try:
            if self.spi:
                start_bit = 0b11
                single_ended_bit = 0b10000000
                channel_bits = self.channels << 4
                dummy_byte = 0b00000000
                self.spi.xfer2([start_bit, single_ended_bit | channel_bits, dummy_byte])
                result = self.spi.xfer2([start_bit, single_ended_bit | channel_bits, dummy_byte])
                return (result[1] << 8) | result[2]
            else:
                return None
        except Exception as e:
            logging.error(f'Error reading SPI: {e}')
            return None

    def read_gpio(self):
        try:
            if self.gpio:
                return GPIO.input(self.gpio_pins)
            else:
                return None
        except Exception as e:
            logging.error(f'Error reading GPIO: {e}')
            return None

    def read_sensor(self):
        if self.sensor_type == 'digital':
            return self.read_gpio()
        elif self.sensor_type == 'analog':
            return self.read_spi()
        else:
            return None

    def log_event(self, event):
        if self.log_queue:
            self.log_queue.put(f'Sensor {self.sensor_id} detected event: {event}')

    def run(self):
        self.thread = threading.Thread(target=self.run_loop)
        self.thread.start()

    def run_loop(self):
        while not self.stop_event.is_set():
            time.sleep(1 / self.sample_rate)
            reading = self.read_sensor()
            if reading is not None:
                if self.sensor_type == 'digital' and reading == 1:
                    self.log_event('sound detected')
                elif self.sensor_type == 'analog' and reading >= self.threshold:
                    self.log_event('sound detected')

    def stop(self):
        self.stop_event.set()
        if self.thread:
            self.thread.join()
        if self.spi:
            self.spi.close()
        if self.gpio:
            GPIO.cleanup()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--sensor_type', required=True, choices=['digital', 'analog'])
    parser.add_argument('--threshold', type=int, default=100)
    parser.add_argument('--sample_rate', type=int, default=10)
    parser.add_argument('--log_file', required=True)
    parser.add_argument('--gpio_pins', type=int, nargs='+')
    parser.add_argument('--channels', type=int, nargs='+')
    parser.add_argument('--spi_speed', type=int, default=1000000)
    parser.add_argument('--sensor_ids', type=int, nargs='+', default=[1, 2])
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(message)s')

    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins[sensor_id-1], args.channels[sensor_id-1], args.spi_speed, log_queue)
        sensor.run()
        sensors.append(sensor)

    try:
        while True:
            message = log_queue.get()
            logging.info(message)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()

if __name__ == '__main__':
    main()

