def preprocess_frame(frame):
    """Preprocesses a frame for inference."""
    try:
        frame = np.expand_dims(frame, axis=0)
        frame = frame.astype(np.float32)
        frame = frame / 255.0
        return frame
    except Exception as e:
        logging.error('Failed to preprocess frame: {}'.format(e))
        sys.exit(0)

