import time
import picamera
import numpy as np
import cv2

class BackgroundModel:
    def __init__(self, learning_rate=0.05):
        self.learning_rate = learning_rate
        self.background = None

    def update(self, image):
        if self.background is None:
            self.background = image.astype(np.float)
        else:
            self.background = (1 - self.learning_rate) * self.background + self.learning_rate * image

    def subtract(self, image):
        return cv2.absdiff(image, cv2.convertScaleAbs(self.background))

class PartCounter:
    def __init__(self, threshold=8.0):
        self.threshold = threshold
        self.count = 0
        self.active = False

    def update(self, image):
        mean = np.mean(image)
        if mean > self.threshold:
            if not self.active:
                self.count += 1
                self.active = True
        else:
            self.active = False

def main():
    with picamera.PiCamera() as camera:
        camera.resolution = (640, 480)
        camera.framerate = 30
        time.sleep(2)

        background_model = BackgroundModel()
        part_counter = PartCounter()

        for _ in camera.capture_continuous(np.empty((480, 640, 3), dtype=np.uint8), format='bgr', use_video_port=True):
            image = _.array
            image = image[120:360, :]
            image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            background_model.update(image)
            part_counter.update(background_model.subtract(image))
            print(part_counter.count)
            time.sleep(0.1)
            _.truncate(0)

if __name__ == '__main__':
    main()

