import subprocess
import threading
import time

import paho.mqtt.client as mqtt

def capture_images():
    while True:
        try:
            subprocess.run(
                ["libcamera-still", "-o", "images/image-%Y%m%d%H%M%S.jpg", "-r", "256x256", "-t", "15000"],
                check=True,
                capture_output=True,
            )
        except subprocess.CalledProcessError as e:
            print(f"Error capturing image: {e}")
        time.sleep(0.5)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker")
        client.subscribe("raspberrypi/control")
    else:
        print(f"Failed to connect to MQTT broker: {rc}")

def on_message(client, userdata, msg):
    try:
        payload = msg.payload.decode("utf-8", "replace")
        print(f"Received message: {payload}")
    except UnicodeDecodeError as e:
        print(f"Error decoding message: {e}")

def main():
    try:
        os.makedirs("images", exist_ok=True)
    except OSError as e:
        print(f"Error creating images directory: {e}")
        return

    capture_thread = threading.Thread(target=capture_images)
    capture_thread.start()

    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_message = on_message

    try:
        mqtt_client.connect("localhost", 1883, 60)
    except mqtt.MQTTException as e:
        print(f"Error connecting to MQTT broker: {e}")
        return

    control_client = mqtt.Client()
    control_client.on_connect = on_connect
    control_client.on_message = on_message

    try:
        control_client.connect("localhost", 1883, 60)
    except mqtt.MQTTException as e:
        print(f"Error connecting to MQTT broker: {e}")
        return

    try:
        mqtt_client.loop_start()
        control_client.loop_start()
    except mqtt.MQTTException as e:
        print(f"Error starting MQTT loops: {e}")
        return

    def signal_handler(signum, frame):
        print("Received signal, stopping capture and control loops")
        mqtt_client.loop_stop()
        control_client.loop_stop()
        mqtt_client.disconnect()
        control_client.disconnect()
        capture_thread.join()
        print("Capture loop stopped, control loop stopped, clients disconnected, capture thread joined")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Keyboard interrupt received, stopping capture and control loops")
        mqtt_client.loop_stop()
        control_client.loop_stop()
        mqtt_client.disconnect()
        control_client.disconnect()
        capture_thread.join()
        print("Capture loop stopped, control loop stopped, clients disconnected, capture thread joined")

if __name__ == "__main__":
    main()

import io
import logging
import numpy as np
import picamera
import picamera.array
import time

class CameraStreamBuffer:
    def __init__(self, camera, output_sink):
        self.camera = camera
        self.output_sink = output_sink
        self.buffer = io.BytesIO()

    def write(self, data):
        self.buffer.write(data)
        if self.camera.frame.complete:
            try:
                self.output_sink.write(self.buffer.getvalue())
            except IOError as e:
                logging.error(e)
            self.buffer.seek(0)
            self.buffer.truncate()

class MotionDetectionBuffer:
    def __init__(self, callback):
        self.callback = callback
        self.previous_frame = None

    def write(self, data):
        if data.startswith(b'\xff\xd8'):
            try:
                with picamera.array.PiMotionAnalysis(self.camera) as stream:
                    stream.write(data)
                    frame = stream.array
                    if self.previous_frame is not None:
                        self.callback(self.previous_frame, frame)
                    self.previous_frame = frame
            except picamera.exc.PiCameraError as e:
                logging.error(e)

with picamera.PiCamera() as camera:
    camera.resolution = (640, 480)
    camera.framerate = 24
    camera.start_recording(CameraStreamBuffer(camera, output_sink), format='mjpeg')
    camera.start_recording(MotionDetectionBuffer(callback), format='mjpeg')
    camera.wait_recording(60)
    camera.stop_recording()

