import os
import sys
import time
import signal
import threading
import picamera
import picamera.array
import cv2
import numpy as np
import paho.mqtt.client as mqtt
from gpiozero import MotionSensor
from twilio.rest import Client

# Twilio credentials
TWILIO_ACCOUNT_SID = os.environ.get('TWILIO_ACCOUNT_SID')
TWILIO_AUTH_TOKEN = os.environ.get('TWILIO_AUTH_TOKEN')
TWILIO_PHONE_NUMBER = os.environ.get('TWILIO_PHONE_NUMBER')
RECIPIENT_PHONE_NUMBER = os.environ.get('RECIPIENT_PHONE_NUMBER')

# Twilio client
twilio_client = Client(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)

# MQTT client
mqtt_client = mqtt.Client()

# Motion sensor
motion_sensor = MotionSensor(4)

# Motion detection
motion_detected = False

# Face detection
face_cascade = cv2.CascadeClassifier('haarcascade_frontalface_default.xml')

# Motion detection cooldown
motion_detection_cooldown = 0

# MQTT message callback
def on_message(client, userdata, message):
    global motion_detected
    if message.topic == 'motion':
        motion_detected = message.payload.decode() == '1'

# MQTT connection callback
def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print('Connected to MQTT broker')
        client.subscribe('motion')
    else:
        print('Failed to connect to MQTT broker')

# MQTT disconnection callback
def on_disconnect(client, userdata, rc):
    if rc != 0:
        print('Disconnected from MQTT broker')

# MQTT error callback
def on_error(client, userdata, error):
    print('MQTT error:', error)

# MQTT message publish
def publish_message(topic, payload):
    mqtt_client.publish(topic, payload)

# Twilio SMS send
def send_sms(message):
    try:
        twilio_client.messages.create(
            from_=TWILIO_PHONE_NUMBER,
            to=RECIPIENT_PHONE_NUMBER,
            body=message
        )
    except Exception as e:
        print('Twilio error:', e)

# Motion detection
def detect_motion(frame):
    global motion_detected
    global motion_detection_cooldown
    if motion_sensor.motion_detected and time.time() > motion_detection_cooldown:
        motion_detected = True
        motion_detection_cooldown = time.time() + 60

# Face detection
def detect_face(frame):
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, 1.3, 5)
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

# Motion detection and face detection
