from adafruit_mcp3xxx.analog_in import AnalogIn
import RPi.GPIO as GPIO

# Set up logging
logging.basicConfig(filename='environmental_monitor.log', level=logging.DEBUG, format='%(asctime)s %(message)s')

# Set up LCD
lcd_rs = digitalio.DigitalInOut(board.D25)
lcd_en = digitalio.DigitalInOut(board.D24)
lcd_d4 = digitalio.DigitalInOut(board.D23)
lcd_d5 = digitalio.DigitalInOut(board.D17)
lcd_d6 = digitalio.DigitalInOut(board.D18)
lcd_d7 = digitalio.DigitalInOut(board.D22)
lcd_backlight = digitalio.DigitalInOut(board.D12)
lcd = characterlcd.Character_LCD_Mono(lcd_rs, lcd_en, lcd_d4, lcd_d5, lcd_d6, lcd_d7, lcd_backlight, cols=16, lines=2)
