    if cooling_led:
        lcd.message += '\nCooling ON'
    else:
        lcd.message += '\nCooling OFF'
    if humidifier_led:
        lcd.message += '\nHumidifier ON'
    else:
        lcd.message += '\nHumidifier OFF'

# Set up temperature and humidity monitoring
