    global temp, hum, cooling_led, humidifier_led
    while True:
        try:
            temp_sensor = AnalogIn(mcp, MCP.P0)
            temp = round((temp_sensor.voltage - 0.5) * 100, 1)
            if temp < 15 or temp > 35:
                logging.error('Temperature out of range: {}'.format(temp))
                continue
            hum_sensor = AnalogIn(mcp, MCP.P1)
            hum = round((hum_sensor.voltage - 0.5) * 100, 1)
