import time
import random
import logging
import requests
import json
import board
import digitalio
import adafruit_character_lcd.character_lcd as characterlcd
import adafruit_mcp3xxx.mcp3008 as MCP
from adafruit_mcp3xxx.analog_in import AnalogIn
import RPi.GPIO as GPIO

# Set up logging
logging.basicConfig(filename='environmental_monitor.log', level=logging.DEBUG, format='%(asctime)s %(message)s')

# Set up LCD
lcd_rs = digitalio.DigitalInOut(board.D25)
lcd_en = digitalio.DigitalInOut(board.D24)
lcd_d4 = digitalio.DigitalInOut(board.D23)
lcd_d5 = digitalio.DigitalInOut(board.D17)
lcd_d6 = digitalio.DigitalInOut(board.D18)
lcd_d7 = digitalio.DigitalInOut(board.D22)
lcd_backlight = digitalio.DigitalInOut(board.D12)
lcd = characterlcd.Character_LCD_Mono(lcd_rs, lcd_en, lcd_d4, lcd_d5, lcd_d6, lcd_d7, lcd_backlight, cols=16, lines=2)
lcd.message = 'Starting...'

# Set up MCP3008
spi = board.SPI()
mcp = MCP.MCP3008(spi)

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(27, GPIO.OUT)
GPIO.setup(4, GPIO.OUT)

# Set up variables
temp = 0
hum = 0
cooling_led = False
humidifier_led = False

# Set up cloud endpoint
CLOUD_ENDPOINT = 'https://httpbin.org/post'

# Set up cloud upload
def upload_to_cloud():
    global temp, hum, cooling_led, humidifier_led
    data = {'temperature': temp, 'humidity': hum, 'cooling_led': cooling_led, 'humidifier_led': humidifier_led}
    try:
        response = requests.post(CLOUD_ENDPOINT, json=data)
        if response.status_code == 200:
            logging.info('Cloud upload successful')
        else:
            logging.error('Cloud upload failed with status code {}'.format(response.status_code))
    except requests.exceptions.RequestException as e:
        logging.error('Cloud upload failed with exception: {}'.format(e))

# Set up LCD update
def update_lcd():
    global temp, hum, cooling_led, humidifier_led
    lcd.clear()
    lcd.message = 'Temp: {}C\nHum: {}%'.format(temp, hum)
    if cooling_led:
        lcd.message += '\nCooling ON'
    else:
        lcd.message += '\nCooling OFF'
    if humidifier_led:
        lcd.message += '\nHumidifier ON'
    else:
        lcd.message += '\nHumidifier OFF'

# Set up temperature and humidity monitoring
def monitor_environment():
    global temp, hum, cooling_led, humidifier_led
    while True:
        try:
            temp_sensor = AnalogIn(mcp, MCP.P0)
            temp = round((temp_sensor.voltage - 0.5) * 100, 1)
            if temp < 15 or temp > 35:
                logging.error('Temperature out of range: {}'.format(temp))
                continue
            hum_sensor = AnalogIn(mcp, MCP.P1)
            hum = round((hum_sensor.voltage - 0.5) * 100, 1)
            if hum < 40 or hum > 80:
                logging.error('Humidity out of range: {}'.format(hum))
                continue
            if temp > 30:
                cooling_led = True
            elif temp < 28:
                cooling_led = False
            if hum < 50:
                humidifier_led = True
            elif hum > 55:
                humidifier_led = False
            GPIO.output(27, cooling_led)
            GPIO.output(4, humidifier_led)
            update_lcd()
            time.sleep(2)
        except Exception as e:
            logging.error('Error monitoring environment: {}'.format(e))

