import time
import spidev

spi = spidev.SpiDev()
spi.open(0, 0)
spi.max_speed_hz = 1000000

def write_register(register, value):
    try:
        spi.xfer2([register, value])
    except spidev.SpiException as e:
        print(f"Error writing to register {register}: {e}")

def set_decode_mode(mode):
    write_register(0x09, mode)

def set_intensity(intensity):
    write_register(0x0A, intensity)

def set_scan_limit(limit):
    write_register(0x0B, limit)

def set_shutdown_mode(mode):
    write_register(0x0C, mode)

def set_display_test(mode):
    write_register(0x0F, mode)

def set_digit(digit, value):
    write_register(digit, value)

def clear_display():
    for digit in range(8):
        set_digit(digit, 0)

def main():
    try:
        set_decode_mode(0)
        set_intensity(0)
        set_scan_limit(7)
        set_shutdown_mode(1)
        set_display_test(0)

        for level in range(9):
            for digit in range(8):
                set_digit(digit, level)
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    finally:
        clear_display()
        set_shutdown_mode(0)
        spi.close()

if __name__ == "__main__":
    main()

