import time
import logging
import subprocess
from gpiozero import LightSensor, MCP3008
from datetime import datetime

# Constants
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75

# Setup logging
logging.basicConfig(
    format='%(asctime)s %(levelname)s %(message)s',
    level=logging.INFO,
    datefmt='%Y-%m-%d %H:%M:%S')

# Setup sensors
light_sensor = LightSensor(17)
temp_sensor = MCP3008(channel=4)

# Setup Pi temperature reading
def get_pi_temp():
    try:
        output = subprocess.check_output(
            ['vcgencmd', 'measure_temp'],
            timeout=5,
            text=True)
        return float(output.split('=')[1].strip()[:-2])
    except Exception as e:
        logging.warning(f'Failed to read Pi temperature: {e}')
        return None

# Setup sensor simulation
def simulate_light():
    try:
        light = light_sensor.value
        if light < 0.2:
            light = 100 + light * 200
        elif light < 0.6:
            light = 300 + light * 700
        else:
            light = 1000 + light * 900
        return light
    except Exception as e:
        logging.warning(f'Failed to simulate light: {e}')
        return 0

def simulate_temp():
    try:
        temp = temp_sensor.value
        return 20 + temp * 10
    except Exception as e:
        logging.warning(f'Failed to simulate temperature: {e}')
        return 0

def simulate_voltage(light):
    try:
        if light > LOW_LIGHT_THRESHOLD:
            return 11.5 + (light - LOW_LIGHT_THRESHOLD) * 0.1
        else:
            return 10.0 + light * 0.1
    except Exception as e:
        logging.warning(f'Failed to simulate voltage: {e}')
        return 0

def simulate_current(light):
    try:
        if light > LOW_LIGHT_THRESHOLD:
            return 1.5 + (light - LOW_LIGHT_THRESHOLD) * 0.1
        else:
            return 0.5 + light * 0.1
    except Exception as e:
        logging.warning(f'Failed to simulate current: {e}')
        return 0

# Setup logging
def log_data(light, temp, voltage, current, pi_temp):
    try:
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        logging.info(f'{timestamp} {light:.0f} {temp:.1f} {voltage:.1f} {current:.1f} {pi_temp:.1f if pi_temp is not None else "N/A"}')
    except Exception as e:
        logging.warning(f'Failed to log data: {e}')

# Main entry point
if __name__ == '__main__':
    try:
        while True:
            light = simulate_light()
            temp = simulate_temp()
            voltage = simulate_voltage(light)
            current = simulate_current(light)
            pi_temp = get_pi_temp()
            log_data(light, temp, voltage, current, pi_temp)
            if light < LOW_LIGHT_THRESHOLD:
                logging.warning('WARNING: Low light detected')
            if temp > HIGH_TEMP_THRESHOLD:
                logging.warning('WARNING: High temperature detected')
                # Simulate cooling activation here
            if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
                logging.critical('CRITICAL: High Pi temperature detected')
                # Simulate system shutdown here
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info('Program interrupted by user')
    finally:
        light_sensor.close()
        temp_sensor.close()

