import time
import logging
import smbus2
import crc8

class DHT20:
    def __init__(self, bus=1, address=0x5c):
        self.bus = smbus2.SMBus(bus)
        self.address = address
        self.last_read = 0
        self.last_result = (None, None, False)

    def begin(self):
        try:
            self.bus.read_byte(self.address)
        except OSError as e:
            logging.warning(f"DHT20: {e}")
            return False
        return True

    def get_temperature_and_humidity(self):
        if time.time() - self.last_read < 2:
            return self.last_result
        for _ in range(5):
            try:
                data = self.bus.read_i2c_block_data(self.address, 0, 7)
            except OSError as e:
                logging.warning(f"DHT20: {e}")
                continue
            if crc8.crc8(data[:6]) != data[6]:
                logging.warning(f"DHT20: CRC error")
                continue
            self.last_read = time.time()
            self.last_result = (data[0] + data[1] / 100, data[2] + data[3] / 100, False)
            return self.last_result
        self.last_result = (None, None, True)
        return self.last_result

    def close(self):
        self.bus.close()

    def __enter__(self):
        self.begin()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

