class FanController(Thread):
    def __init__(self, pin, frequency, step_size, min_duty_cycle, max_duty_cycle):
        super().__init__()
        self.pin = pin
        self.frequency = frequency
        self.step_size = step_size
        self.min_duty_cycle = min_duty_cycle
        self.max_duty_cycle = max_duty_cycle
        self.duty_cycle = 0
        self.pwm = None
        self.running = False

    def run(self):
        self.running = True
        try:
            self.pwm = PWMOutputDevice(self.pin, frequency=self.frequency)
        except Exception as e:
            logger.warning(f'Failed to initialize PWM output on pin {self.pin}: {e}')
            self.pwm = None
        while self.running:
            if self.pwm:
                self.pwm.value = self.duty_cycle
            time.sleep(5)
            try:
                self.duty_cycle = self.get_duty_cycle()
            except Exception as e:
                logger.warning(f'Failed to get duty cycle: {e}')

    def get_duty_cycle(self):
        temperature = self.get_temperature()
        if temperature is None:
            return self.duty_cycle
        if temperature < 40:
            return self.min_duty_cycle
        if temperature > 60:
            return self.max_duty_cycle
        return self.min_duty_cycle + (temperature - 40) * self.step_size

    def get_temperature(self):
        try:
            output = subprocess.check_output(['vcgencmd', 'measure_temp']).decode('utf-8')
            return float(output.split('=')[1].split('\'')[0])
        except Exception as e:
            logger.warning(f'Failed to get temperature: {e}')
            return None

    def stop(self):
        self.running = False
        if self.pwm:
            self.pwm.close()


def main():
    fan_controller = FanController(pin=14, frequency=100, step_size=0.01, min_duty_cycle=0.1, max_duty_cycle=0.9)
    fan_controller.start()
    signal.signal(signal.SIGINT, lambda signum, frame: fan_controller.stop())
    signal.signal(signal.SIGTERM, lambda signum, frame: fan_controller.stop())
    while fan_controller.is_alive():
        time.sleep(1)


