import atexit
import time
import board
import busio
import adafruit_pca9685

class Fuchikoma:
    def __init__(self):
        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.pca = adafruit_pca9685.PCA9685(self.i2c)
            self.pca.frequency = 60
            self.pca.channels[0].duty_cycle = 0
            self.pca.channels[1].duty_cycle = 0
            self.pca.channels[2].duty_cycle = 0
            atexit.register(self.cleanup)
        except (ValueError, OSError) as e:
            print(e)
            exit(1)

    def cleanup(self):
        self.pca.channels[0].duty_cycle = 0
        self.pca.channels[1].duty_cycle = 0
        self.pca.channels[2].duty_cycle = 0
        self.i2c.deinit()

    def move_servo(self, channel, angle):
        if angle < -77 or angle > 77:
            raise ValueError("Angle must be between -77 and 77")
        pulse_width = 150 + (angle + 77) * 1.8
        self.pca.channels[channel].duty_cycle = int(pulse_width * 65535 / 1000000)
        time.sleep(0.029)
        self.pca.channels[channel].duty_cycle = 0

    def bite(self):
        self.move_servo(0, -75)

    def open_claw(self):
        self.move_servo(0, 75)

    def lock(self):
        self.move_servo(1, 75)

    def unlock(self):
        self.move_servo(1, -75)

    def shoot(self):
        self.move_servo(2, -75)

    def load_water(self):
        self.move_servo(2, 75)

