    stream=sys.stderr,
)

# Set up signal handlers
def signal_handler(signum, frame):
    logging.info("Received signal %d, shutting down", signum)
    sys.exit(0)


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Set up GPS
GPS_PORT = "/dev/serial0"
GPS_BAUD = 9600
GPS_TIMEOUT = 2

gps = serial.Serial(GPS_PORT, GPS_BAUD, timeout=GPS_TIMEOUT)

# Set up TCP server
TCP_HOST = "127.0.0.1"
TCP_PORT = 9099

server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
server.bind((TCP_HOST, TCP_PORT))
server.listen()

# Set up tracking state
tracking_state = "stopped"

# Set up simulated GPS coordinates
simulated_gps_coordinates = {
    "lat": 40.730610,
    "lon": -73.935242,
}


def read_gps_position():
    """Read GPS position from the GPS module."""
    try:
        gps_data = gps.readline().decode("utf-8")
        logging.debug("GPS data: %s", gps_data)
        if "GPRMC" in gps_data:
            gps_data = gps_data.split(",")
            if gps_data[2] == "A":
                return {
                    "lat": float(gps_data[3]),
                    "lon": float(gps_data[5]),
                }
    except serial.SerialException as e:
        logging.error("Error reading GPS data: %s", e)
    return None


def handle_command(command):
    """Handle a command from the client."""
    if command == "start":
        global tracking_state
        tracking_state = "running"
        return "Tracking started"
    elif command == "stop":
        global tracking_state
        tracking_state = "stopped"
        return "Tracking stopped"
    elif command == "report":
        if tracking_state == "running":
            gps_position = read_gps_position()
            if gps_position is not None:
                return json.dumps(gps_position)
            else:
                return json.dumps(simulated_gps_coordinates)
        else:
            return "Tracking is not running"
    else:
        return "Invalid command"


def main():
    """Main loop."""
    while True:
        try:
            client, address = server.accept()
            logging.info("Accepted connection from %s", address)
            command = client.recv(1024).decode("utf-8").strip()
            logging.info("Received command: %s", command)
            response = handle_command(command)
            logging.info("Sending response: %s", response)
            client.send(response.encode("utf-8"))
            client.close()
        except socket.error as e:
            logging.error("Error handling connection: %s", e)


