import serial
import time
import logging
import sys
import signal
import binascii

class ModbusRTU:
    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = serial.Serial(port, baudrate, timeout=timeout)
        self.serial.flushInput()
        self.serial.flushOutput()

    def read_holding_registers(self, address, count):
        if not self.serial.isOpen():
            self.serial.open()
        try:
            self.serial.flushInput()
            self.serial.flushOutput()
            self.serial.write(self.build_read_holding_registers_request(address, count))
            response = self.read_response()
            if response:
                return self.parse_read_holding_registers_response(response)
            else:
                return None
        except serial.SerialException as e:
            logging.warning(e)
            return None
        finally:
            self.serial.close()

    def write_single_register(self, address, value):
        if not self.serial.isOpen():
            self.serial.open()
        try:
            self.serial.flushInput()
            self.serial.flushOutput()
            self.serial.write(self.build_write_single_register_request(address, value))
            response = self.read_response()
            if response:
                return self.parse_write_single_register_response(response)
            else:
                return None
        except serial.SerialException as e:
            logging.warning(e)
            return None
        finally:
            self.serial.close()

    def write_multiple_registers(self, address, values):
        if not self.serial.isOpen():
            self.serial.open()
        try:
            self.serial.flushInput()
            self.serial.flushOutput()
            self.serial.write(self.build_write_multiple_registers_request(address, values))
            response = self.read_response()
            if response:
                return self.parse_write_multiple_registers_response(response)
            else:
                return None
        except serial.SerialException as e:
            logging.warning(e)
            return None
        finally:
            self.serial.close()

    def read_response(self):
        response = self.serial.read(self.serial.inWaiting())
        if response:
            if self.validate_response(response):
                return response
            else:
                logging.warning("CRC error")
                return None
        else:
            logging.warning("No response")
            return None

    def validate_response(self, response):
        if len(response) < 2:
            return False
        crc = binascii.crc32(response[:-2]) & 0xffffffff
        if crc == int.from_bytes(response[-2:], byteorder='big'):
            return True
        else:
            return False

    def build_read_holding_registers_request(self, address, count):
        request = bytearray([0x01, 0x03, address >> 8, address & 0xff, count >> 8, count & 0xff])
        crc = binascii.crc32(request) & 0xffffffff
        request.append(crc >> 24)
        request.append(crc >> 16)
        request.append(crc >> 8)
        request.append(crc & 0xff)
        return request

    def parse_read_holding_registers_response(self, response):
        if len(response) < 5:
            return None
        count = response[2]
        if len(response) != 5 + count:
            return None
        return response[3:3+count]

    def build_write_single_register_request(self, address, value):
        request = bytearray([0x01, 0x06, address >> 8, address & 0xff, value >> 8, value & 0xff])
        crc = binascii.crc32(request) & 0xffffffff
        request.append(crc >> 24)
        request.append(crc >> 16)
        request.append(crc >> 8)
        request.append(crc & 0xff)
        return request

    def parse_write_single_register_response(self, response):
        if len(response) != 8:
            return None
        return response[4:6]

    def build_write_multiple_registers_request(self, address, values):
        count = len(values)
        request = bytearray([0x01, 0x10, address >> 8, address & 0xff, count >> 8, count & 0xff, count * 2])
        for value in values:
            request.append(value >> 8)
            request.append(value & 0xff)
        crc = binascii.crc32(request) & 0xffffffff
        request.append(crc >> 24)
        request.append(crc >> 16)
        request.append(crc >> 8)
        request.append(crc & 0xff)
        return request

    def parse_write_multiple_registers_response(self, response):
        if len(response) != 8:
            return None
        return response[4:6]

def signal_handler(sig, frame):
    logging.warning('Exiting...')
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    logging.basicConfig(level=logging.WARNING, format='%(asctime)s - %(levelname)s - %(message)s')
