import threading
import serial
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class WaterFlowReader(threading.Thread):
    def __init__(self, event):
        super().__init__()
        self.event = event
        self.serial = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)

    def run(self):
        while not self.event.is_set():
            try:
                line = self.serial.readline().decode('ascii', 'replace').strip()
                try:
                    flow_rate = float(line)
                    logging.info(f'{time.strftime("%Y-%m-%dT%H:%M:%S%z")} - Flow Rate: {flow_rate} L/min')
                    with open('water_flow_log.txt', 'a') as f:
                        f.write(f'{time.strftime("%Y-%m-%dT%H:%M:%S%z")} - Flow Rate: {flow_rate} L/min\n')
                except ValueError:
                    logging.warning(f'Invalid flow rate: {line}')
            except serial.SerialException as e:
                logging.error(f'Serial error: {e}')
                break
        self.serial.close()

def main():
    event = threading.Event()
    thread = WaterFlowReader(event)
    thread.start()
    try:
        while True:
            time.sleep(1)
    except (KeyboardInterrupt, SystemExit):
        event.set()
        thread.join()

