from dataclasses import dataclass
from typing import Optional
from serial import Serial
from serial.serialutil import SerialException
from logging import getLogger, basicConfig, DEBUG
from signal import signal, SIGINT, SIGTERM
from sys import exit
from time import sleep
from re import compile, match
from math import floor

basicConfig(level=DEBUG)
logger = getLogger(__name__)

@dataclass
class GPS_reading:
    latitude: float
    longitude: float
    altitude: float
    satellite_count: int

class GPSReader:
    def __init__(self, port: str, baudrate: int, timeout: float):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None

    def connect(self):
        try:
            self.serial = Serial(self.port, self.baudrate, timeout=self.timeout)
        except SerialException as e:
            logger.error(f"Failed to open {self.port}: {e}")
            exit(1)

    def disconnect(self):
        if self.serial:
            self.serial.close()
            self.serial = None

    def read(self) -> Optional[GPS_reading]:
        try:
            line = self.serial.readline().decode()
        except SerialException as e:
            logger.warning(f"Failed to read from {self.port}: {e}")
            return None

        if not line:
            return None

        m = match(r"^$GPGGA,(\d\d\d\d\d\d\.\d\d),([NS]),(\d\d\d\d\d\d\.\d\d),([EW]),(\d),(\d\d),(\d\d\.\d),(-?\d\d\d\d\.\d\d),M,(\d\d\d\d\.\d\d),M,,", line)
        if not m:
            logger.warning(f"Invalid GPGGA sentence: {line}")
            return None

        try:
            latitude = float(m.group(1))
            latitude_sign = 1 if m.group(2) == "N" else -1
            longitude = float(m.group(3))
            longitude_sign = 1 if m.group(4) == "E" else -1
            satellite_count = int(m.group(5))
            altitude = float(m.group(7))
        except ValueError as e:
            logger.warning(f"Invalid GPGGA sentence: {line}: {e}")
            return None

        return GPS_reading(
            latitude=latitude_sign * (floor(latitude / 100) + (latitude % 100) / 60),
            longitude=longitude_sign * (floor(longitude / 100) + (longitude % 100) / 60),
            altitude=altitude,
            satellite_count=satellite_count,
        )

def main():
    reader = GPSReader("/dev/serial0", 9600, 1)
    reader.connect()
    signal(SIGINT, lambda signum, frame: reader.disconnect())
    signal(SIGTERM, lambda signum, frame: reader.disconnect())
    try:
        while True:
            reading = reader.read()
            if reading:
                logger.debug(f"Read: {reading}")
            sleep(1)
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

class ESP8266:
    def __init__(self):
        self.port = serial.Serial(
            port='/dev/ttyS0',
            baudrate=115200,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=5,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
            write_timeout=None,
            inter_byte_timeout=None,
            exclusive=None
        )

    def _send_command(self, command, delay=1, max_retries=3):
        for i in range(max_retries):
            self.port.write(command.encode())
            time.sleep(delay)
            response = self._read_response()
            if response:
                return response
        return None

    def _read_response(self):
        response = self.port.read_until(b'\r\n')
        if response:
            return response.decode().strip()
        return None

    def test_connection(self):
        response = self._send_command('AT\r\n')
        if response == 'OK':
            return True
        return False

    def restart(self):
        response = self._send_command('AT+RST\r\n', delay=2)
        if response == 'OK':
            return True
        return False

    def connect_wifi(self, ssid, password):
        response = self._send_command(f'AT+CWJAP_CUR="{ssid}","{password}"\r\n', delay=5)
        if response == 'WIFI GOT IP':
            return True
        return False

def signal_handler(sig, frame):
    print('Exiting...')
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

