import serial
import time
import signal
import sys

class GPS:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.ser = None
        try:
            self.ser = serial.Serial(self.port, self.baud, timeout=1)
        except serial.SerialException as e:
            print(e)
            sys.exit(1)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def attach(self):
        self.ser.write(b'AT+CGNSPWR=1\r\n')
        time.sleep(1)
        if self.ser.in_waiting > 0:
            return True
        else:
            return False

    def detach(self):
        self.ser.write(b'AT+CGNSPWR=0\r\n')
        time.sleep(1)
        if self.ser.in_waiting > 0:
            return True
        else:
            return False

    def get_data(self):
        if self.ser.in_waiting > 0:
            data = self.ser.readline().decode('utf-8')
            if data.startswith('$GPRMC') and data.split(',')[2] == 'A':
                return data.split(',')
            else:
                return None
        else:
            return None

    def close(self):
        if self.ser:
            self.ser.close()

def signal_handler(sig, frame):
    print('Exiting...')
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GPS() as gps:
        if gps.attach():
            print('GPS attached')
        else:
            print('GPS attach failed')
            sys.exit(1)

        while True:
            data = gps.get_data()
            if data:
                print(data)
            else:
                print('No data')
            time.sleep(1)

        if gps.detach():
            print('GPS detached')
        else:
            print('GPS detach failed')
            sys.exit(1)

