import serial
import re

class SimpleGPS:
    def __init__(self):
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial('/dev/serial0', 9600, timeout=1)
            return True
        except OSError:
            return False

    def read_data(self):
        try:
            return self.ser.readline().decode('utf-8').strip()
        except (OSError, AttributeError):
            return None

    def parse_gga(self, line):
        try:
            if line.startswith('$GPGGA') or line.startswith('$GNGGA'):
                fields = line.split(',')
                return {
                    'utc_time': fields[1],
                    'latitude': float(fields[2]) if fields[2] else None,
                    'longitude': float(fields[4]) if fields[4] else None,
                    'fix_quality': int(fields[6]) if fields[6] else None,
                    'num_satellites': int(fields[7]) if fields[7] else None
                }
            else:
                return None
        except (IndexError, ValueError):
            return None

    def close(self):
        try:
            self.ser.close()
        except AttributeError:
            pass
        self.ser = None

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    gps = SimpleGPS()
    if gps.connect():
        try:
            while True:
                line = gps.read_data()
                if line:
                    gga = gps.parse_gga(line)
                    if gga:
                        logging.info(gga)
        except KeyboardInterrupt:
            pass
        finally:
            gps.close()
    else:
        logging.error('Failed to connect to GPS')

import serial
import threading
import time
