from flask import Flask, request, jsonify

app = Flask(__name__)

class SerialPort:
    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.lock = threading.Lock()
        self.serial = None

    def __enter__(self):
        self.lock.acquire()
        if self.serial is None:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
        return self.serial

    def __exit__(self, exc_type, exc_value, traceback):
        if self.serial is not None:
            self.serial.close()
            self.serial = None
        self.lock.release()

class Data:
    def __init__(self, name, done):
        self.id = None
        self.name = name
        self.done = done

data = [Data("item1", False), Data("item2", True)]

@app.route('/version', methods=['GET'])
def version():
    try:
        with SerialPort('/dev/ttyUSB0', 9600, 1) as serial:
            serial.write(b'*IDN?\n')
            serial.flush()
            response = serial.readline()
            return response.decode('ascii'), 200
    except serial.SerialException:
        return 'Serial port error', 500
    except serial.SerialTimeoutException:
        return 'Timeout', 504
    except Exception:
        return 'Unknown error', 502

@app.route('/data', methods=['GET'])
def get_data():
    return jsonify([item.__dict__ for item in data]), 200

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    for item in data:
        if item.id == item_id:
            return jsonify(item.__dict__), 200
    return 'Item not found', 404

@app.route('/data', methods=['POST'])
def post_data():
    try:
        name = request.json['name']
        done = request.json['done']
    except KeyError:
        return 'Invalid request', 400
    if not name:
        return 'Invalid name', 400
    item = Data(name, done)
    item.id = len(data) + 1
    data.append(item)
    return jsonify(item.__dict__), 201

def signal_handler(sig, frame):
    print('Exiting...')
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)

